contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        (uint oldUnlockTime, uint oldBal) = c.Acc(address(this));
        uint oldCBal = address(c).balance;

        c.Put{value: amount}(lockTime);

        (uint newUnlockTime, uint newBal) = c.Acc(address(this));
        uint newCBal = address(c).balance;

        assert(newBal == oldBal + amount);
        assert(newCBal == oldCBal + amount);
        assert(newUnlockTime >= block.timestamp && newUnlockTime >= oldUnlockTime);
    }

    receive() external payable {}
}

