contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint lockTime) public payable {
        require(address(this).balance >= amount);

        // Read the before-state through the public Acc getter.
        (, uint beforeBalance) = c.Acc(address(this));

        // Decide whether the Put call should succeed by checking whether Log is set.
        // The LogFile public getter returns an address; if it is zero, Put will revert inside Log.AddMessage.
        address logAddr = address(c.Log());
        bool expectSuccess = logAddr != address(0);

        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        if (expectSuccess) {
            assert(!reverted);
            assert(afterBalance == beforeBalance + amount);
            assert(afterUnlock >= block.timestamp);
        } else {
            assert(reverted);
            assert(afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

