        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(lockTime);
        c.Initialized();

        uint balBefore = address(c).balance;
        bool expectedSuccess = collectAmount <= putAmount && collectAmount <= balBefore;

        bool success;
        try c.Collect(collectAmount) { success = true; } catch { success = false; }

