contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint initVal, address logAddr) public payable {
        // Pre-initialize the contract with a known MinSum and Log address.
        c.SetMinSum(initVal);
        uint beforeMinSum = c.MinSum();
        c.SetLogFile(logAddr);
        c.Initialized();

        // Any later attempt to replace these setup values must fail.
        bool setMinReverted;
        try c.SetMinSum(initVal + 1) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }
        bool setLogReverted;
